#!/usr/bin/env python3
"""
Author repair_protocols for 9 platforms (birds + scooters + drones + AMR)
with 5-6 failure-mode gaps each: bird_three, lime_gen4, rad_commercial,
amazon_proteus, dji_agras_t50, dji_matrice_350, dji-agras-t60, skydio_x10,
starship_gen3.

Each protocol operationalizes the FM's documented mitigation into a real procedure.
Parts are generic/field-standard; source_url = engineering-estimate.
Idempotent: skips FM IDs that already have a protocol.

Usage: python3 build_drones_scooters_amr_repair_protocols.py [--dry-run]
"""
import json, subprocess, sys, os, re

DRY = '--dry-run' in sys.argv
HOME = os.path.expanduser("~")

def q(sql):
    out = subprocess.run(["supabase", "db", "query", "--linked", sql],
                         capture_output=True, text=True, cwd=HOME)
    raw = out.stdout
    s = raw.find("{")
    if s == -1:
        return []
    try:
        return json.loads(raw[s:]).get("rows", [])
    except Exception:
        m = re.search(r'"rows"\s*:\s*(\[.*\])\s*}', raw, re.S)
        return json.loads(m.group(1)) if m else []

def run(sql):
    r = subprocess.run(["supabase", "db", "query", "--linked", sql],
                       capture_output=True, text=True, cwd=HOME)
    if r.returncode != 0:
        raise RuntimeError(f"SQL failed: {(r.stderr or r.stdout)[:400]}")
    return r.stdout

